package com.yonlab.vision;
import org.junit.Test;
import static org.junit.Assert.*;

public class OneDeviceSupportPolicyTest {
 @Test public void noticesAreIsolatedByDeviceVersionFeatureAndModel(){String a=OneDeviceSupportPolicy.key("fold6","14","detect","a");assertNotEquals(a,OneDeviceSupportPolicy.key("board","14","detect","a"));assertNotEquals(a,OneDeviceSupportPolicy.key("fold6","15","detect","a"));assertNotEquals(a,OneDeviceSupportPolicy.key("fold6","14","classify","a"));assertNotEquals(a,OneDeviceSupportPolicy.key("fold6","14","detect","b"));assertEquals(a,OneDeviceSupportPolicy.key("fold6","14","detect","a"));}
 @Test public void completedWithNoRecognitionRemainsSuccessful(){assertEquals("COMPLETED",OneDeviceSupportPolicy.outcome("COMPLETED","",""));assertFalse(OneDeviceSupportPolicy.noticeRequired("COMPLETED"));}
 @Test public void actualFailureAndNativeCloseFailureRequireNotice(){for(String state:new String[]{"ERROR","FAILED","UNSUPPORTED"})assertTrue(OneDeviceSupportPolicy.noticeRequired(OneDeviceSupportPolicy.outcome(state,"IOException","")));assertEquals("ERROR",OneDeviceSupportPolicy.outcome("CLOSED","UnsatisfiedLinkError","ERROR"));}
 @Test public void cancellationAndIntermediateStatesNeverBecomeUnsupported(){for(String state:new String[]{"CANCELED","CANCELLED","STOPPED","RUNNING","PREPARING","CLOSING"})assertEquals("",OneDeviceSupportPolicy.outcome(state,"InterruptedIOException","BACKGROUND"));assertEquals("",OneDeviceSupportPolicy.outcome("CLOSED","","BACKGROUND"));}
 @Test public void successfulRetryClearsOnlyItsOwnActiveNotice(){assertTrue(OneDeviceSupportPolicy.noticeRequired("ERROR"));assertFalse(OneDeviceSupportPolicy.noticeRequired(OneDeviceSupportPolicy.outcome("COMPLETED","","")));assertEquals("COMPLETED",OneDeviceSupportPolicy.outcome("CLOSED","","COMPLETE"));}
 @Test public void rawExceptionMessagesAreNotStoredAsDeviceCodes(){assertEquals("MODEL_CLEANUP",OneDeviceSupportPolicy.code("MODEL_CLEANUP"));assertEquals("RUN_FAILED",OneDeviceSupportPolicy.code("file /private/user-photo.jpg failed"));assertEquals("RUN_FAILED",OneDeviceSupportPolicy.code(null));}
 @Test public void inputFailureIsObservedEvenWithoutModelExecution(){assertEquals("ERROR",OneDeviceSupportPolicy.pipelineOutcome("ERROR","IOException",0));assertEquals("ERROR",OneDeviceSupportPolicy.pipelineOutcome("ERROR","InputCleanup",2));assertEquals("",OneDeviceSupportPolicy.pipelineOutcome("PARTIAL_ERROR","",0));}
 @Test public void successfulModelWithCleanPipelineClearsOnlyInputNotice(){assertEquals("COMPLETED",OneDeviceSupportPolicy.pipelineOutcome("COMPLETED","",1));assertEquals("COMPLETED",OneDeviceSupportPolicy.pipelineOutcome("PARTIAL_ERROR","",1));assertEquals("COMPLETED",OneDeviceSupportPolicy.pipelineOutcome("ERROR","",1));assertEquals("",OneDeviceSupportPolicy.pipelineOutcome("ERROR","",0));assertEquals("",OneDeviceSupportPolicy.pipelineOutcome("COMPLETED","",0));assertEquals("",OneDeviceSupportPolicy.pipelineOutcome("CANCELED","InterruptedIOException",1));assertNotEquals(OneDeviceSupportPolicy.key("fold6","14","sound","@input"),OneDeviceSupportPolicy.key("fold6","14","sound","yamnet-classifier"));}
 @Test public void liveClosedAfterObservedInferenceCanClearOldError(){assertEquals("COMPLETED",OneDeviceSupportPolicy.liveOutcome("CLOSED","",3,true,true,true,true));assertEquals("",OneDeviceSupportPolicy.liveOutcome("RUNNING","",3,true,true,true,true));}
 @Test public void zeroFrameAndIncompleteLiveCleanupCannotClearOldError(){assertEquals("",OneDeviceSupportPolicy.liveOutcome("CLOSED","",0,true,true,true,true));assertEquals("",OneDeviceSupportPolicy.liveOutcome("CLOSED","",3,false,true,true,true));assertEquals("",OneDeviceSupportPolicy.liveOutcome("CLOSED","",3,true,false,true,true));assertEquals("",OneDeviceSupportPolicy.liveOutcome("CLOSED","",3,true,true,false,true));assertEquals("",OneDeviceSupportPolicy.liveOutcome("CLOSED","",3,true,true,true,false));assertEquals("ERROR",OneDeviceSupportPolicy.liveOutcome("CLOSED","NativeCleanup",3,true,true,true,false));}
 @Test public void comparisonGroupIsCanonicalAndDoesNotGuessFromIntent(){assertEquals("KO",OneDeviceSupportPolicy.group("KO"));assertEquals("GO",OneDeviceSupportPolicy.group("GO"));assertEquals("ALL",OneDeviceSupportPolicy.group("ALL"));assertEquals("ALL",OneDeviceSupportPolicy.group(null));assertEquals("ALL",OneDeviceSupportPolicy.group("ko"));}
}
